   </section>
   <footer class="footer"><span>STAY MOBILE. KEEP FIRING.</span><span>BUILT FOR <b>THE LAST CUBE STANDING</b></span></footer>
 </main>
 <script>
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const W=960,H=600,ui={score:document.getElementById('score'),kills:document.getElementById('kills'),wave:document.getElementById('wave'),waveFill:document.getElementById('waveFill'),healthText:document.getElementById('healthText'),healthFill:document.getElementById('healthFill'),dash:document.getElementById('dashMeter'),toast:document.getElementById('toast'),pause:document.getElementById('pauseChip')};
+const overlays={start:document.getElementById('startOverlay'),upgrade:document.getElementById('upgradeOverlay'),over:document.getElementById('gameOverOverlay')};
+let state='menu',last=0,keys={},mouse={x:W/2,y:H/2,active:false},touchMove=null,touchAim=null,worldTime=0,shake=0,toastTimer=0;
+let player,enemies,shots,particles,pickups,score,kills,wave,spawnLeft,spawnClock,clearClock,fireClock,shotsFired,damageFlash,upgrades;
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+function freshRun(){player={x:W/2,y:H/2,r:14,hp:100,maxHp:100,speed:235,fireRate:.29,damage:1,bulletSpeed:580,bulletSize:4,pierce:0,dash:3,dashMax:3,dashWait:0,dashCooldown:1.6,invuln:0,dx:1,dy:0};enemies=[];shots=[];particles=[];pickups=[];score=0;kills=0;wave=1;spawnLeft=7;spawnClock=.8;clearClock=-1;fireClock=.2;shotsFired=0;damageFlash=0;upgrades={};worldTime=0;updateHud()}
+function startRun(){freshRun();state='playing';overlays.start.classList.add('hidden');overlays.over.classList.add('hidden');overlays.upgrade.classList.add('hidden');ui.pause.classList.remove('show');last=performance.now()}
+function showToast(t){ui.toast.textContent=t;ui.toast.classList.add('show');toastTimer=1.5}
+function updateHud(){ui.score.textContent=String(score).padStart(4,'0');ui.kills.textContent=kills;ui.wave.textContent=String(wave).padStart(2,'0');let total=Math.max(1,wave*5+2);ui.waveFill.style.width=(100*(1-spawnLeft/total))+'%';ui.healthText.textContent=Math.max(0,Math.ceil(player?.hp||0))+'%';ui.healthFill.style.width=clamp((player?.hp||0)/(player?.maxHp||100)*100,0,100)+'%';ui.dash.innerHTML=Array.from({length:player?.dashMax||3},(_,i)=>`<i class="dash-dot ${i<(player?.dash||0)?'ready':''}"></i>`).join('')}
+function spawnEnemy(){let a=Math.random()*Math.PI*2,edge=Math.floor(Math.random()*4),x,y;if(edge===0){x=rand(30,W-30);y=20}else if(edge===1){x=W-20;y=rand(30,H-30)}else if(edge===2){x=rand(30,W-30);y=H-20}else{x=20;y=rand(30,H-30)}let kind=wave>=3&&Math.random()<.22?'heavy':wave>=2&&Math.random()<.33?'runner':'chaser';let spec=kind==='heavy'?{r:19,hp:3+Math.floor(wave/5),speed:54+Math.min(wave*2,25),color:'#b982ff',value:35}:{r:kind==='runner'?10:13,hp:kind==='runner'?1:1+Math.floor(wave/7),speed:kind==='runner'?126+Math.min(wave*2,30):78+Math.min(wave*2.2,45),color:kind==='runner'?'#ffbf6b':'#ff6687',value:kind==='runner'?20:15};enemies.push({x,y,vx:0,vy:0,kind,...spec,maxHp:spec.hp,hit:0,angle:rand(0,6.28),phase:rand(0,6.28)})}
+function burst(x,y,color,n=8,power=150){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.2,.55),max:.55,size:rand(2,5),color})}}
+function nearest(){let best=null,bd=Infinity;for(let e of enemies){let d=(e.x-player.x)**2+(e.y-player.y)**2;if(d<bd){bd=d;best=e}}return best}
+function fire(){let target=nearest();if(!target)return;let dx=target.x-player.x,dy=target.y-player.y,len=Math.hypot(dx,dy)||1;let spread=mouse.active&&Math.hypot(mouse.x-player.x,mouse.y-player.y)>80?.035:0;let a=Math.atan2(dy,dx)+rand(-spread,spread);shots.push({x:player.x+Math.cos(a)*17,y:player.y+Math.sin(a)*17,vx:Math.cos(a)*player.bulletSpeed,vy:Math.sin(a)*player.bulletSpeed,life:1.25,damage:player.damage,pierce:player.pierce,r:player.bulletSize});fireClock=player.fireRate;shotsFired++}
+function dash(){if(state!=='playing'||player.dash<1)return;let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(touchMove){x=touchMove.dx;y=touchMove.dy}let l=Math.hypot(x,y);if(l<.1){x=player.dx;y=player.dy;l=1}player.dx=x/l;player.dy=y/l;player.x=clamp(player.x+player.dx*115,25,W-25);player.y=clamp(player.y+player.dy*115,25,H-25);player.dash--;player.invuln=.48;player.dashWait=player.dashCooldown;shake=7;burst(player.x,player.y,'#62e8ff',12,190);updateHud()}
+function update(dt){worldTime+=dt;shake=Math.max(0,shake-dt*20);damageFlash=Math.max(0,damageFlash-dt*2);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}player.invuln=Math.max(0,player.invuln-dt);if(player.dash<player.dashMax){player.dashWait-=dt;if(player.dashWait<=0){player.dash++;player.dashWait=player.dash<player.dashMax?player.dashCooldown:0;updateHud()}}
+let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(touchMove){mx=touchMove.dx;my=touchMove.dy}let ml=Math.hypot(mx,my);if(ml>0){mx/=ml;my/=ml;player.x=clamp(player.x+mx*player.speed*dt,22,W-22);player.y=clamp(player.y+my*player.speed*dt,22,H-22);player.dx=mx;player.dy=my}
+fireClock-=dt;if(fireClock<=0&&enemies.length)fire();
+if(spawnLeft>0){spawnClock-=dt;if(spawnClock<=0){spawnEnemy();spawnLeft--;spawnClock=Math.max(.24,.83-wave*.035)*rand(.72,1.22)}}else if(enemies.length===0){if(clearClock<0){clearClock=1.1;showToast('WAVE '+String(wave).padStart(2,'0')+' CLEARED');player.hp=Math.min(player.maxHp,player.hp+8);updateHud()}else{clearClock-=dt;if(clearClock<=0){if(wave%3===0){openUpgrades();return}wave++;spawnLeft=5+wave*2;clearClock=-1;spawnClock=.9;showToast('WAVE '+String(wave).padStart(2,'0')+' INCOMING');updateHud()}}}
+for(let e of enemies){e.phase+=dt*3;e.angle+=dt*(e.kind==='runner'?1.5:.6);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.vx=dx/d*e.speed;e.vy=dy/d*e.speed;e.x+=e.vx*dt;e.y+=e.vy*dt;e.hit=Math.max(0,e.hit-dt);if(d<e.r+player.r+1&&player.invuln<=0){player.hp-=e.kind==='heavy'?17:11;player.invuln=.62;damageFlash=.75;shake=5;let knock=Math.max(1,d);player.x=clamp(player.x-dx/knock*24,20,W-20);player.y=clamp(player.y-dy/knock*24,20,H-20);burst(player.x,player.y,'#ff6687',7,130);updateHud();if(player.hp<=0){endRun();return}}}
+for(let b of shots){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(let e of enemies){if(e.hp<=0)continue;if(Math.hypot(e.x-b.x,e.y-b.y)<e.r+b.r){e.hp-=b.damage;e.hit=.12;burst(b.x,b.y,e.color,3,75);if(b.pierce>0)b.pierce--;else b.life=0;if(e.hp<=0){score+=e.value+wave;kills++;burst(e.x,e.y,e.color,11,190);if(Math.random()<.08)pickups.push({x:e.x,y:e.y,r:7,life:8})}break}}}shots=shots.filter(b=>b.life>0&&b.x>-30&&b.x<W+30&&b.y>-30&&b.y<H+30);enemies=enemies.filter(e=>e.hp>0);
+for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);
+for(let p of pickups){p.life-=dt;let d=Math.hypot(player.x-p.x,player.y-p.y);if(d<player.r+p.r+7){player.hp=Math.min(player.maxHp,player.hp+14);p.life=0;burst(p.x,p.y,'#a6ffcb',8,100);showToast('HULL REPAIRED +14');updateHud()}}pickups=pickups.filter(p=>p.life>0);updateHud()}
+function endRun(){state='over';ui.pause.classList.remove('show');document.getElementById('finalStats').textContent=`You survived ${wave} wave${wave===1?'':'s'} and eliminated ${kills} cubes. Final score: ${score}.`;overlays.over.classList.remove('hidden')}

