const upgradePool=[{icon:'⚡',name:'Overclock',desc:'Fire 22% faster. Make every second count.',apply:()=>player.fireRate*=.78},{icon:'✦',name:'Hot Rounds',desc:'Deal +1 damage with every shot.',apply:()=>player.damage++},{icon:'➤',name:'Phase Drive',desc:'Move 18% faster and dash recharges sooner.',apply:()=>{player.speed*=1.18;player.dashCooldown*=.78}},{icon:'⬡',name:'Reinforced Hull',desc:'Restore 35 hull and increase max hull by 15.',apply:()=>{player.maxHp+=15;player.hp=Math.min(player.maxHp,player.hp+35)}},{icon:'◎',name:'Rail Core',desc:'Shots pierce one extra cube and fly faster.',apply:()=>{player.pierce++;player.bulletSpeed*=1.12}},{icon:'✚',name:'Dash Cell',desc:'Gain one additional dash charge.',apply:()=>{player.dashMax++;player.dash++}}];
function openUpgrades(){state='upgrade';overlays.upgrade.classList.remove('hidden');let choices=[...upgradePool].sort(()=>Math.random()-.5).slice(0,3),box=document.getElementById('upgradeCards');box.innerHTML='';for(let u of choices){let b=document.createElement('button');b.className='upgrade-card';b.innerHTML=`<div class="upgrade-icon">${u.icon}</div><div class="upgrade-title">${u.name}</div><div class="upgrade-desc">${u.desc}</div>`;b.onclick=()=>{u.apply();overlays.upgrade.classList.add('hidden');wave++;spawnLeft=5+wave*2;spawnClock=.8;clearClock=-1;state='playing';showToast(u.name.toUpperCase()+' ONLINE');updateHud()};box.appendChild(b)}}
function cube(x,y,r,color,angle=0,glow=0,hit=0){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.shadowColor=color;ctx.shadowBlur=glow;let d=r*.32;ctx.fillStyle=hit>0?'#fff':color;ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.beginPath();ctx.rect(-r,-r,r*2,r*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.globalAlpha=.72;ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(-r,-r);ctx.lineTo(-r+d,-r-d*.75);ctx.lineTo(r+d,-r-d*.75);ctx.lineTo(r,-r);ctx.closePath();ctx.fill();ctx.globalAlpha=.45;ctx.fillStyle='#020611';ctx.beginPath();ctx.moveTo(r,-r);ctx.lineTo(r+d,-r-d*.75);ctx.lineTo(r+d,r-d*.75);ctx.lineTo(r,r);ctx.closePath();ctx.fill();ctx.globalAlpha=1;if(r>14){ctx.fillStyle='#fff';ctx.globalAlpha=.75;ctx.fillRect(-3,-2,2,2);ctx.fillRect(2,-2,2,2)}ctx.restore()}
function draw(){ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));ctx.clearRect(-20,-20,W+40,H+40);let bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#0c1624');bg.addColorStop(.55,'#0a111d');bg.addColorStop(1,'#101525');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
ctx.strokeStyle='#8ca1bd0a';ctx.lineWidth=1;for(let x=0;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
for(let i=0;i<60;i++){let x=(i*173+19)%W,y=(i*97+53)%H;ctx.fillStyle=`rgba(135,180,220,${.06+.05*Math.sin(worldTime+i)})`;ctx.fillRect(x,y,1.5,1.5)}
ctx.strokeStyle='#54677d55';ctx.setLineDash([5,8]);ctx.strokeRect(18,18,W-36,H-36);ctx.setLineDash([]);
for(let p of pickups){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(worldTime*2);ctx.shadowColor='#a6ffcb';ctx.shadowBlur=16;ctx.fillStyle='#a6ffcb';ctx.fillRect(-5,-5,10,10);ctx.restore()}
for(let b of shots){ctx.save();ctx.strokeStyle='#a6ffcb';ctx.lineWidth=2;ctx.shadowColor='#a6ffcb';ctx.shadowBlur=12;ctx.beginPath();ctx.moveTo(b.x-b.vx*.025,b.y-b.vy*.025);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore()}
for(let e of enemies){if(e.maxHp>1){ctx.fillStyle='#182234';ctx.fillRect(e.x-e.r,e.y-e.r-8,e.r*2,3);ctx.fillStyle=e.color;ctx.fillRect(e.x-e.r,e.y-e.r-8,e.r*2*e.hp/e.maxHp,3)}cube(e.x,e.y,e.r,e.color,e.angle,8,e.hit)}
for(let p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=10;ctx.fillRect(p.x-p.size/2,p.y-p.size/2,p.size,p.size)}ctx.globalAlpha=1;ctx.shadowBlur=0;
if(player){if(player.invuln>0&&Math.floor(worldTime*18)%2===0)ctx.globalAlpha=.45;cube(player.x,player.y,player.r,'#a6ffcb',Math.sin(worldTime*1.5)*.045,18);ctx.globalAlpha=1;ctx.strokeStyle='#a6ffcb88';ctx.lineWidth=1;ctx.beginPath();ctx.arc(player.x,player.y,player.r+7+Math.sin(worldTime*4)*1.5,0,Math.PI*2);ctx.stroke();if(mouse.active&&state==='playing'){let t=nearest();if(t){ctx.strokeStyle='#a6ffcb30';ctx.setLineDash([3,8]);ctx.beginPath();ctx.moveTo(player.x,player.y);ctx.lineTo(t.x,t.y);ctx.stroke();ctx.setLineDash([])}}}
if(damageFlash>0){ctx.fillStyle=`rgba(255,60,100,${damageFlash*.12})`;ctx.fillRect(0,0,W,H)}let vignette=ctx.createRadialGradient(W/2,H/2,120,W/2,H/2,570);vignette.addColorStop(0,'transparent');vignette.addColorStop(1,'#03060a99');ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H);ctx.restore()}

